/* storage_info without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then storage_info_result. */
static inline status_t storage_info_send(handle_t ch, uint32_t idl_txid)
{
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    _Alignas(8) uint8_t idl_b0[8];
    struct storage_info_req *idl_q = (struct storage_info_req *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = idl_txid;
    idl_q->ordinal = STORAGE_INFO;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* The status and results of a reply to storage_info_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t storage_info_result(const void *idl_rep, struct idl_msg *idl_m, char out_vendor[8 + 1], uint32_t *out_vendor_len, char out_product[16 + 1], uint32_t *out_product_len, uint32_t *out_block_size, uint64_t *out_blocks, uint8_t *out_scheme, uint32_t *out_partitions, uint32_t *out_mbr_id, uint8_t out_disk_guid[16])
{
    const struct storage_info_rep *idl_r = (const struct storage_info_rep *)idl_rep;
    uint32_t idl_o = sizeof(*idl_r);
    status_t idl_st = idl_rep_status_var(idl_rep, idl_m->n, sizeof(*idl_r));
    const void *idl_p0 = NULL;
    uint32_t idl_l0 = 0;
    const void *idl_p1 = NULL;
    uint32_t idl_l1 = 0;
    if (idl_st == OK && !idl_get(idl_rep, idl_m->n, &idl_o, 8, 1, &idl_p0, &idl_l0))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !idl_get(idl_rep, idl_m->n, &idl_o, 16, 1, &idl_p1, &idl_l1))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !idl_str_ok((const char *)idl_p1, idl_l1))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_o != idl_m->n)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_m->nh != 0)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    idl_m->nh = 0;
    if (out_block_size)
        *out_block_size = idl_r->block_size;
    if (out_blocks)
        *out_blocks = idl_r->blocks;
    if (out_scheme)
        *out_scheme = idl_r->scheme;
    if (out_partitions)
        *out_partitions = idl_r->partitions;
    if (out_mbr_id)
        *out_mbr_id = idl_r->mbr_id;
    for (uint32_t idl_i = 0; out_disk_guid && idl_i < 16; idl_i++)
        out_disk_guid[idl_i] = idl_r->disk_guid[idl_i];
    if (out_vendor) {
        if (idl_l0)
            __builtin_memcpy(out_vendor, idl_p0, idl_l0 * 1);
        out_vendor[idl_l0] = 0;
    }
    if (out_vendor_len)
        *out_vendor_len = idl_l0;
    if (out_product) {
        if (idl_l1)
            __builtin_memcpy(out_product, idl_p1, idl_l1 * 1);
        out_product[idl_l1] = 0;
    }
    if (out_product_len)
        *out_product_len = idl_l1;
    return OK;
}

